import registry from './generated-listing-models.json';
import {propertyModels,type PropertyModel} from './lib/property-models';

type Listing={real?:boolean;reference?:string;source?:{id?:string};models?:PropertyModel[]};

/**
 * Listing models: a reviewed model stored with the listing wins; otherwise the
 * photo-based schematic generated by scripts/listing-models (matched on both
 * the listing reference and its source id, so a reused reference never gets
 * another property's model).
 */
export function listingModels(item:Listing):PropertyModel[]|undefined{
  if(!item.real)return undefined;
  if(item.models?.length)return item.models;
  const entry=(registry as Record<string,{sourceId:string;models:unknown}>)[item.reference||''];
  if(!entry||!item.source?.id||entry.sourceId!==item.source.id)return undefined;
  const models=propertyModels(entry.models);
  return models.length?models:undefined;
}
